//! Symbol map of the shipped firmware binary (`data/v1.71_symbols.json`, generated by
//! `tools/symbol_map.py` from the relocations of the GCC 11.3 reference build).

use crate::firmware::Symbol;
use anyhow::{anyhow, Context, Result};
use std::collections::HashMap;

/// The symbol map for the shipped v1.71 payload, embedded at compile time.
pub const V171_SYMBOLS_JSON: &str = include_str!("../data/v1.71_symbols.json");

/// Size of the v1.71 payload the symbol map was made for.
pub const V171_PAYLOAD_SIZE: usize = 273_528;
/// SHA-256 of the v1.71 payload (the bytes after the 16 byte image header).
pub const V171_PAYLOAD_SHA256: &str =
    "5d52310ebbc1cd028e9b89a44f220c6d9b9a7e6e446d8a8559bce63df481bea0";

fn parse_hex(s: &str) -> Result<u32> {
    u32::from_str_radix(s.trim_start_matches("0x"), 16).map_err(|e| anyhow!("bad address {s}: {e}"))
}

/// Parse a symbol map JSON (functions + data) into the `Firmware` symbol table.
/// Functions whose size is unknown in the shipped binary get their size from our build
/// (`elf_size`); it is only informative.
pub fn parse_symbol_map(json: &str) -> Result<HashMap<String, Symbol>> {
    let v: serde_json::Value = serde_json::from_str(json).context("symbol map JSON")?;
    let mut out = HashMap::new();
    for section in ["functions", "data"] {
        let Some(obj) = v.get(section).and_then(|x| x.as_object()) else {
            continue;
        };
        for (name, e) in obj {
            let addr = parse_hex(
                e["addr"]
                    .as_str()
                    .ok_or_else(|| anyhow!("{name}: no addr"))?,
            )?;
            let size = e
                .get("size")
                .and_then(|s| s.as_u64())
                .or_else(|| e.get("elf_size").and_then(|s| s.as_u64()))
                .unwrap_or(0) as u32;
            out.insert(name.clone(), Symbol { addr, size });
        }
    }
    Ok(out)
}

/// Split an SD-card update image (`LXRV2IMG` header, 16 bytes) into its payload.
pub fn image_payload(img: &[u8]) -> Result<&[u8]> {
    if img.len() < 16 || &img[0..8] != b"LXRV2IMG" {
        return Err(anyhow!("not an LXRV2IMG image"));
    }
    let size = u32::from_le_bytes(img[8..12].try_into().unwrap()) as usize;
    if img.len() < 16 + size {
        return Err(anyhow!(
            "image truncated: header says {size} bytes, file has {}",
            img.len() - 16
        ));
    }
    // checksum: sum of payload bytes + header checksum byte == 0xff
    let sum = img[16..16 + size]
        .iter()
        .fold(0u8, |a, b| a.wrapping_add(*b))
        .wrapping_add(img[12]);
    if sum != 0xff {
        return Err(anyhow!("image checksum mismatch"));
    }
    Ok(&img[16..16 + size])
}
